  private static File findPlantUMLJar() throws IOException {
    Object markdownPlugin = PluginManagerCore.getPlugin(PluginId.getId("org.intellij.plugins.markdown"));
    if (markdownPlugin == null) {
      throw new IOException("The MPS Markdown plugin is required to provide PlantUML");
    }
    try {
      ClassLoader markdownClassLoader = (ClassLoader) markdownPlugin.getClass().getMethod("getPluginClassLoader").invoke(markdownPlugin);
      Class<?> managerClass = markdownClassLoader.loadClass("org.intellij.plugins.markdown.extensions.common.plantuml.PlantUMLJarManager");
      Object manager = managerClass.getMethod("getInstance").invoke(null);
      Method findPath = managerClass.getDeclaredMethod("findPath");
      findPath.setAccessible(true);
      File jar = (File) findPath.invoke(manager);
      if (jar == null) {
        throw new IOException("The MPS Markdown plugin returned no PlantUML cache path");
      }
      if (!(jar.isFile())) {
        downloadPlantUMLJar(markdownClassLoader, jar);
      }
      try (JarFile archive = new JarFile(jar)) {
        if (archive.getJarEntry("net/sourceforge/plantuml/SourceStringReader.class") == null) {
          throw new IOException("The PlantUML jar in the Markdown plugin cache is invalid: " + jar);
        }
      }
      return jar;
    } catch (InvocationTargetException e) {
      throw new IOException("Could not locate PlantUML in the MPS Markdown plugin", e.getCause());
    } catch (ReflectiveOperationException e) {
      throw new IOException("Could not locate PlantUML in the MPS Markdown plugin", e);
    }
  }
  private static void downloadPlantUMLJar(ClassLoader markdownClassLoader, File target) throws IOException, ReflectiveOperationException {
    Class<?> providerClass = markdownClassLoader.loadClass("org.intellij.plugins.markdown.extensions.common.plantuml.PlantUMLCodeGeneratingProvider");
    Object provider = providerClass.getDeclaredConstructor().newInstance();
    Iterable<?> files = (Iterable<?>) providerClass.getMethod("getFilesToDownload").invoke(provider);
    for (Object entry : files) {
      String filePath = (String) entry.getClass().getMethod("getFilePath").invoke(entry);
      if (!(new File(filePath).getName().equals(target.getName()))) {
        continue;
      }
      Supplier<?> linkSupplier = (Supplier<?>) entry.getClass().getMethod("getLink").invoke(entry);
      URL url = URI.create(String.valueOf(linkSupplier.get())).toURL();
      if (!("https".equalsIgnoreCase(url.getProtocol()))) {
        throw new IOException("PlantUML must be downloaded over HTTPS");
      }
      Path targetPath = target.toPath();
      Path directory = targetPath.getParent();
      if (directory == null) {
        throw new IOException("The Markdown plugin returned an invalid PlantUML cache path: " + target);
      }
      Files.createDirectories(directory);
      Path temporaryFile = Files.createTempFile(directory, "plantuml-", ".jar");
      try {
        URLConnection connection = url.openConnection();
        connection.setConnectTimeout(15000);
        connection.setReadTimeout(60000);
        try (InputStream input = connection.getInputStream()) {
          if (!("https".equalsIgnoreCase(connection.getURL().getProtocol()))) {
            throw new IOException("PlantUML download redirected away from HTTPS");
          }
          Files.copy(input, temporaryFile, StandardCopyOption.REPLACE_EXISTING);
        }
        if (Files.size(temporaryFile) == 0) {
          throw new IOException("PlantUML download was empty");
        }
        Files.move(temporaryFile, targetPath, StandardCopyOption.REPLACE_EXISTING);
      } finally {
        Files.deleteIfExists(temporaryFile);
      }
      return;
    }
    throw new IOException("The MPS Markdown plugin did not provide a PlantUML download");
  }
